// For #genuary2026, day 03: "fibonacci forever".

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	background(0);
	types = [OPEN, CHORD, PIE];
	dim = -PI;
	tindex = 2;
	sequence = generateFibonacci(15);
	lastdim = dim;
}

function draw() {
	let bEnergy = (window.beatEnergy || 0.0);
	dim = 2 * TAU * sin((frameCount / 300) * (1.0 + bEnergy * 2.0));
	lastdim = dim;
	rotateZ(dim / 2);
	rotateY(dim / 2);
	rotateX(dim / 2);
	drawCurl();
}

function drawCurl() {
	for (let i = 0; i < sequence.length; i++) {
		let r = sequence[i] * dim;
		noFill();
		let bEnergy = (window.beatEnergy || 0.0);
	stroke(color(0, 240, 255, 80));
		strokeWeight(0.2);
		if (i > 2) translate(-(sequence[i - 1] * abs(dim)) / 2 + (sequence[i - 3] * abs(dim)) / 2, 0);
		arc(0, 0, r, r, 0, HALF_PI, types[tindex]);
		rotate(HALF_PI);
	}
}

function mousePressed() {
	fullscreen(true);
	tindex = (tindex + 1) % types.length;
	background(0);
}

function generateFibonacci(n) {
	let fib = [0, 1];
	for (let i = 2; i < n; i++) {
		fib.push(fib[i - 1] + fib[i - 2]);
	}
	return fib;
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

